import numpy as np


class MetricsCalculator2:
    def __init__(self):
        pass

    @staticmethod
    def _compute_ranking_array(length):
        return 1.0 / (np.array(list(range(length))) + 1)

    @staticmethod
    def _compute_mrr_single(sub_list, total_num):
        sub_list = np.array(sub_list)
        if total_num == 0:
            return 0.0

        ranking_array = MetricsCalculator2._compute_ranking_array(len(sub_list))
        mr_np = sub_list * ranking_array

        mr = 0.0
        for team in mr_np:
            if team > 0:
                mr = team
                break
        return mr

    @staticmethod
    def _compute_ap_single(sub_list, total_num):
        sub_list = np.array(sub_list)
        if total_num == 0:
            return 0.0

        ranking_array = MetricsCalculator2._compute_ranking_array(len(sub_list))

        right_ranking_list = []
        count = 1
        for t in sub_list:
            if t == 0:
                right_ranking_list.append(0)
            else:
                right_ranking_list.append(count)
                count += 1

        ap = np.sum(np.array(right_ranking_list) * ranking_array) / total_num
        return ap

    @staticmethod
    def _validate_input(data):
        if type(data) != list and type(data) != tuple:
            raise Exception("the input must be a tuple([0,...,1,...],int) or a iteration of list of tuple")
        if len(data) == 0:
            return 0.0, [0.0]

    @staticmethod
    def mrr(data):
        validation_result = MetricsCalculator2._validate_input(data)
        if validation_result is not None:
            return validation_result

        if type(data) == tuple:
            (sub_list, total_num) = data
            mr = MetricsCalculator2._compute_mrr_single(sub_list, total_num)
            return mr, [mr]

        if type(data) == list:
            separate_result = [
                MetricsCalculator2._compute_mrr_single(sub_list, total_num)
                for (sub_list, total_num) in data
            ]
            return np.mean(separate_result), separate_result

    @staticmethod
    def map(data):
        validation_result = MetricsCalculator2._validate_input(data)
        if validation_result is not None:
            return validation_result

        if type(data) == tuple:
            (sub_list, total_num) = data
            ap = MetricsCalculator2._compute_ap_single(sub_list, total_num)
            return ap, [ap]

        if type(data) == list:
            separate_result = [
                MetricsCalculator2._compute_ap_single(sub_list, total_num)
                for (sub_list, total_num) in data
            ]
            return np.mean(separate_result), separate_result
